  Definition put_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (b : Z) (es : list mbe) (insz n src E lo B : Z) (bs : list byte) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (errv' : word) (s' : PState) (p : bptr) (x : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz n) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom usegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv usegs m' /\ stk usegs m' lo (bv_unsigned sp)
      /\ rw_cells usegs m' (errno_addr tp) [C4 errv'] /\ hs_rauxv_ok H m' B
      /\ hs_RHEAP H s' (mb_new_blocks es insz n p x ++ LB) m'
      /\ (mb_need es insz n = true -> rblock_range x (mb_block_size (mb_grow es insz n))
                                       /\ forall a k, rclient_range LB (bv_unsigned sp) a k -> 0 <= k -> a + k <= x \/ x + mb_block_size (mb_grow es insz n) <= a)
      /\ MBuf m' b (mb_put_es es insz n x) (insz + n) /\ MBufOwn (mb_new_blocks es insz n p x ++ LB) (mb_put_es es insz n x)
      /\ rw_cells usegs m' E (ErrCodeCells EC_clear)
      /\ bytes_at usegs m' src bs
