      rw_cells usegs m cbp [C8 (wz src); C8 (wz n)] -> bv_unsigned sp <= cbp -> (cbp + 16 <= b \/ b + 64 <= cbp) -> cbp + 16 <= B ->
      rw_cells usegs m E [CB 24 ej] -> bv_unsigned sp <= E -> (E + 24 <= b \/ b + 64 <= E) -> E + 24 <= B ->
      (rd + 8 <= E \/ E + 24 <= rd) -> (cbp + 16 <= E \/ E + 24 <= cbp) ->
      bytes_at usegs m src bs -> zlength bs = n -> rclient_range LB (bv_unsigned sp) src n ->
      (forall x' s', In (x', s') es -> src + n <= x' \/ x' + 24 + s' <= src) -> (src + n <= b \/ b + 64 <= src) ->
      (src + n <= E \/ E + 24 <= src) ->
      bv_unsigned sp <= b -> b + 64 <= B ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      (mb_need es insz n = true -> lb_bytes LB + mb_block_size (mb_grow es insz n) <= hs_LIVE_MAX H) ->
      (mb_need es insz n = true -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H) ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B -> B <= 2^64 ->
      stk usegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - PUT_STACK -> bv_unsigned sp mod 16 = 0 ->
      bv_unsigned ra mod 2 = 0 ->
      rw_cells usegs m (errno_addr tp) [C4 errv] -> mem_inv usegs m -> tp = Z_to_bv 64 RATP ->
      (* [comment removed for export] *)
